UPDATE spots SET lat = 36.0029991, lng = 139.3973159, description = '高坂駅西口を起点に、旧鉄道の廃線敷を利用したまなびのみち、岩殿丘陵の市民の森、物見山付近、高坂彫刻プロムナードをつなぐ参考周回です。舗装路に加え、未舗装の散策路や急な階段を含みます。', access = '東武東上線の高坂駅西口を起点に進みます。駅前や住宅地では歩行者を優先してください。', updated_at = unixepoch() * 1000 WHERE id = '5c2b5a96-d7cb-49af-bb59-c44c2ad7a135' AND lat IS 36.002832 AND lng IS 139.396662 AND description IS '東武東上線高坂駅西口から旧日本セメント専用線の廃線跡を転用した遊歩道を西へ進み、大東文化大学前の急坂を上って岩殿観音(正法寺)と物見山公園へ。JAXA地球観測センター前まで足を延ばし、こども動物自然公園前を通って駅に戻る約15.5kmの丘陵周回。舗装路と土の道が交互に現れ、起伏走やクロカン練習に向く。物見山公園と岩殿観音周辺にトイレ・自販機あり。' AND access IS '東武東上線 高坂駅';
